def pretty(s):
 # Human-readable prose only; preserve code, hashes and link targets exactly.
 pattern=r"(```[\s\S]*?```|`[^`]*`|\]\([^)]*\)|\b[0-9a-f]{40,64}\b)"
 parts=re.split(pattern,s)
 for i in range(0,len(parts),2):
  t=parts[i]
  t=re.sub(r",(?=\S)",", ",t);t=re.sub(r";(?=\S)","; ",t)
  t=re.sub(r":(?=[A-Za-zÁÉÍÓÚáéíóú0-9])",": ",t)
  t=re.sub(r"(\d)([A-Za-záéíóúñÁÉÍÓÚ]{3,})",r"\1 \2",t)
  t=re.sub(r"(Node|pnpm|PostgreSQL|Total|las|los|conservan|repetido|sexta|con|sin|de)(?=\d)",r"\1 ",t)
  for a,b in [('Tasks§','Tasks §'),('Plan§','Plan §'),('SPEC§','SPEC §'),('Las187','Las 187'),('decisionesD','decisiones D'),('completa19','completa 19'),('Matriz26','Matriz 26'),('previoI','previo I'),('sinvaloresficticios','sin valores ficticios'),('no nuevos','no nuevos')]:t=t.replace(a,b)
  parts[i]=t
 return ''.join(parts)

